from pathlib import Path
from datetime import datetime
import shutil

ROOT = Path(__file__).resolve().parent

FILES = {
    "views": ROOT / "accounts" / "views.py",
    "template": ROOT / "templates" / "accounts" / "public_profile.html",
    "css": ROOT / "static" / "css" / "public-profile.css",
    "tests": ROOT / "accounts" / "test_public_profile_v2.py",
}

def read(path):
    if not path.exists():
        raise SystemExit(f"Dosya bulunamadı: {path}")
    return path.read_text(encoding="utf-8")

def write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\\n")
    print(f"GÜNCELLENDİ: {path.relative_to(ROOT)}")

backup = ROOT / f"_backup_public_profile_{datetime.now():%Y%m%d_%H%M%S}"
backup.mkdir(parents=True, exist_ok=True)

for path in FILES.values():
    if path.exists():
        target = backup / path.relative_to(ROOT)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, target)

views = read(FILES["views"])
start = views.find("def public_profile(request, username):")
end_marker = "\n\n@role_required(User.UserType.USER)\ndef profile(request):"
end = views.find(end_marker, start)

if start == -1 or end == -1:
    raise SystemExit(
        "accounts/views.py içinde public_profile fonksiyonu bulunamadı."
    )

new_function = 'def public_profile(request, username):\n    account = get_object_or_404(\n        User.objects.only(\n            "pk",\n            "username",\n            "first_name",\n            "last_name",\n            "date_joined",\n            "user_type",\n            "selected_avatar",\n            "profile_image",\n            "is_active",\n        ),\n        username=username,\n        user_type=User.UserType.USER,\n        is_active=True,\n    )\n\n    badges = resolve_user_badges(account)\n\n    from django.core.paginator import Paginator\n\n    from complaints.forms import UserReportForm\n    from complaints.models import (\n        Complaint,\n        ComplaintComment,\n        ComplaintReaction,\n        UserReport,\n    )\n    from complaints.selectors import public_complaints\n\n    public_complaint_qs = public_complaints().filter(\n        user=account,\n    )\n\n    complaint_count = public_complaint_qs.count()\n\n    resolved_count = public_complaint_qs.filter(\n        status=Complaint.Status.RESOLVED,\n    ).count()\n\n    comment_count = ComplaintComment.objects.filter(\n        author_user=account,\n        is_active=True,\n        complaint__status__in=(\n            Complaint.Status.PUBLISHED,\n            Complaint.Status.RESOLVED,\n        ),\n        complaint__withdrawn_at__isnull=True,\n        complaint__removed_for_violation=False,\n        complaint__company__is_active=True,\n    ).count()\n\n    received_reaction_count = ComplaintReaction.objects.filter(\n        complaint__user=account,\n        complaint__status__in=(\n            Complaint.Status.PUBLISHED,\n            Complaint.Status.RESOLVED,\n        ),\n        complaint__withdrawn_at__isnull=True,\n        complaint__removed_for_violation=False,\n        complaint__company__is_active=True,\n    ).count()\n\n    complaint_page = Paginator(\n        public_complaint_qs,\n        6,\n    ).get_page(\n        request.GET.get("complaint_page")\n    )\n\n    viewer_is_user = (\n        request.user.is_authenticated\n        and request.user.user_type == User.UserType.USER\n    )\n\n    is_self = (\n        viewer_is_user\n        and request.user.pk == account.pk\n    )\n\n    viewer_is_suspended = (\n        viewer_is_user\n        and getattr(\n            request.user,\n            "is_currently_suspended",\n            False,\n        )\n    )\n\n    already_reported = False\n\n    if viewer_is_user and not is_self:\n        already_reported = UserReport.objects.filter(\n            reporter=request.user,\n            reported_user=account,\n        ).exists()\n\n    can_report = (\n        viewer_is_user\n        and not is_self\n        and not viewer_is_suspended\n        and not already_reported\n    )\n\n    return render(\n        request,\n        "accounts/public_profile.html",\n        {\n            "account": account,\n            "user_badges": badges,\n            "primary_user_badge": primary_badge(badges),\n            "complaint_count": complaint_count,\n            "resolved_count": resolved_count,\n            "comment_count": comment_count,\n            "received_reaction_count": received_reaction_count,\n            "complaint_page": complaint_page,\n            "viewer_is_user": viewer_is_user,\n            "is_self": is_self,\n            "viewer_is_suspended": viewer_is_suspended,\n            "can_report": can_report,\n            "already_reported": already_reported,\n            "user_report_form": UserReportForm(),\n        },\n    )\n'
views = views[:start] + new_function + views[end:]
write(FILES["views"], views)

template = '{% extends "base.html" %}\n{% load static %}\n\n{% block title %}@{{ account.username }} | DertDerman{% endblock %}\n{% block body_class %}public-site public-profile-page{% endblock %}\n\n{% block extra_head %}\n<link rel="stylesheet" href="{% static \'css/public-profile.css\' %}">\n<link rel="stylesheet" href="{% static \'css/report-modal.css\' %}">\n<script src="{% static \'js/report-modal.js\' %}" defer></script>\n{% endblock %}\n\n{% block content %}\n<main class="public-profile-shell" id="main-content">\n    <section class="public-profile-card">\n        <header class="public-profile-hero">\n            <div class="public-profile-identity">\n                {% include \'components/user_avatar.html\' with user=account size_class=\'profile-avatar\' only %}\n\n                <div class="public-profile-copy">\n                    <p class="public-profile-kicker">DERTDERMAN KULLANICISI</p>\n                    <h1>@{{ account.username }}</h1>\n\n                    {% if account.get_full_name %}\n                        <p class="public-profile-name">{{ account.get_full_name }}</p>\n                    {% endif %}\n\n                    <p class="public-profile-member-since">\n                        {{ account.date_joined|date:"Y" }}\'dan beri DertDerman\'da\n                    </p>\n\n                    {% if primary_user_badge %}\n                        <div class="public-profile-primary-badge">\n                            {% include \'components/public_user_badge.html\' with badge=primary_user_badge only %}\n                        </div>\n                    {% endif %}\n                </div>\n            </div>\n\n            <div class="public-profile-hero-actions">\n                {% if can_report %}\n                    <button\n                        type="button"\n                        class="report-trigger public-profile-report-trigger"\n                        data-report-open="user-report-dialog"\n                    >\n                        ⚑ Raporla\n                    </button>\n                {% elif already_reported %}\n                    <span class="public-profile-report-state">✓ Raporlandı</span>\n                {% endif %}\n            </div>\n        </header>\n\n        <div class="public-profile-body">\n            <section class="public-profile-stats" aria-label="Kullanıcı istatistikleri">\n                <article class="public-profile-stat">\n                    <strong>{{ complaint_count }}</strong>\n                    <span>Yayınlanmış şikayet</span>\n                </article>\n\n                <article class="public-profile-stat public-profile-stat--success">\n                    <strong>{{ resolved_count }}</strong>\n                    <span>Çözülen şikayet</span>\n                </article>\n\n                <article class="public-profile-stat public-profile-stat--comment">\n                    <strong>{{ comment_count }}</strong>\n                    <span>Topluluk yorumu</span>\n                </article>\n\n                <article class="public-profile-stat public-profile-stat--reaction">\n                    <strong>{{ received_reaction_count }}</strong>\n                    <span>Şikayetlerine gelen tepki</span>\n                </article>\n            </section>\n\n            {% if user_badges %}\n                <section class="public-profile-section public-profile-badges" aria-labelledby="public-user-badges">\n                    <div class="public-profile-section-heading">\n                        <div>\n                            <p class="section-kicker">TOPLULUK PROFİLİ</p>\n                            <h2 id="public-user-badges">Başarı Rozetleri</h2>\n                        </div>\n                    </div>\n\n                    <div class="achievement-grid">\n                        {% for badge in user_badges %}\n                            {% include \'components/achievement_badge.html\' with badge=badge badge_kind=\'user\' only %}\n                        {% endfor %}\n                    </div>\n                </section>\n            {% endif %}\n\n            <section class="public-profile-section public-profile-complaints" aria-labelledby="public-user-complaints">\n                <div class="public-profile-section-heading">\n                    <div>\n                        <p class="section-kicker">PAYLAŞILAN DENEYİMLER</p>\n                        <h2 id="public-user-complaints">Kullanıcının Şikayetleri</h2>\n                        <p>\n                            Yalnızca yayında olan veya çözüme ulaşmış herkese açık\n                            şikayetler gösterilir.\n                        </p>\n                    </div>\n\n                    <span class="public-profile-total">{{ complaint_count }} kayıt</span>\n                </div>\n\n                {% if complaint_page.object_list %}\n                    <div class="public-profile-complaint-list">\n                        {% for complaint in complaint_page %}\n                            <article class="public-profile-complaint">\n                                <div class="public-profile-complaint-company">\n                                    <span class="public-profile-company-logo">\n                                        {% include \'components/company_avatar.html\' with company=complaint.company image_class=\'public-profile-company-logo-image\' fallback_class=\'public-profile-company-logo-fallback\' only %}\n                                    </span>\n\n                                    <div>\n                                        <strong>{{ complaint.company.name }}</strong>\n                                        <time datetime="{{ complaint.created_at|date:\'c\' }}">\n                                            {{ complaint.created_at|date:\'d.m.Y\' }}\n                                        </time>\n                                    </div>\n\n                                    {% include \'complaints/status_badge.html\' with complaint=complaint only %}\n                                </div>\n\n                                <h3>\n                                    <a href="{% url \'complaints:public_detail\' complaint.pk %}">\n                                        {{ complaint.title }}\n                                    </a>\n                                </h3>\n\n                                <p>{{ complaint.description|truncatechars:180 }}</p>\n\n                                <footer>\n                                    <div class="public-profile-complaint-metrics">\n                                        <span title="Görüntülenme">\n                                            {% include \'components/icon.html\' with name=\'eye\' %}\n                                            {{ complaint.view_count|default:0 }}\n                                        </span>\n                                        <span>Tepki {{ complaint.reaction_count|default:0 }}</span>\n                                        <span>Yorum {{ complaint.comment_count|default:0 }}</span>\n                                    </div>\n\n                                    <a\n                                        class="public-profile-complaint-link"\n                                        href="{% url \'complaints:public_detail\' complaint.pk %}"\n                                    >\n                                        Şikayeti Gör →\n                                    </a>\n                                </footer>\n                            </article>\n                        {% endfor %}\n                    </div>\n\n                    {% include \'components/pagination.html\' with page_obj=complaint_page page_param=\'complaint_page\' label=\'Kullanıcının şikayet sayfaları\' %}\n                {% else %}\n                    <div class="public-profile-empty">\n                        <span aria-hidden="true">◇</span>\n                        <h3>Henüz herkese açık şikayeti yok</h3>\n                        <p>\n                            Bu kullanıcıya ait yayınlanmış veya çözüme ulaşmış\n                            bir şikayet bulunmuyor.\n                        </p>\n                    </div>\n                {% endif %}\n            </section>\n        </div>\n    </section>\n</main>\n\n{% if can_report %}\n<div\n    class="report-modal"\n    id="user-report-dialog"\n    data-report-modal\n    hidden\n    aria-hidden="true"\n    role="dialog"\n    aria-modal="true"\n    aria-labelledby="user-report-title"\n>\n    <div class="report-modal-card">\n        <header class="report-modal-head">\n            <div>\n                <p class="report-modal-kicker">KULLANICI RAPORU</p>\n                <h2 id="user-report-title">@{{ account.username }} kullanıcısını raporla</h2>\n                <p>\n                    Yalnızca topluluk kurallarını ihlal ettiğini düşündüğünüz\n                    davranışları raporlayın.\n                </p>\n            </div>\n\n            <button\n                type="button"\n                class="report-modal-close"\n                data-report-close\n                aria-label="Pencereyi kapat"\n            >\n                ×\n            </button>\n        </header>\n\n        <form\n            method="post"\n            action="{% url \'complaints:user_report\' account.pk %}"\n            class="report-modal-body"\n        >\n            {% csrf_token %}\n\n            <label class="report-modal-field">\n                <span>Raporlama nedeni</span>\n                {{ user_report_form.reason }}\n            </label>\n\n            <label class="report-modal-field">\n                <span>Açıklama</span>\n                {{ user_report_form.description }}\n            </label>\n\n            <p class="report-modal-note">\n                Asılsız veya kötü niyetli raporlar hesap moderasyonuna konu olabilir.\n            </p>\n\n            <div class="report-modal-actions">\n                <button type="button" class="report-cancel" data-report-close>\n                    Vazgeç\n                </button>\n\n                <button type="submit" class="report-submit">\n                    Raporu Gönder\n                </button>\n            </div>\n        </form>\n    </div>\n</div>\n{% endif %}\n{% endblock %}\n'
write(FILES["template"], template)

