tests = 'from django.contrib.auth import get_user_model\nfrom django.test import TestCase\nfrom django.urls import reverse\n\nfrom companies.models import Company\nfrom complaints.models import (\n    Complaint,\n    ComplaintComment,\n    ComplaintReaction,\n    UserReport,\n)\n\n\nUser = get_user_model()\n\n\nclass PublicProfileV2Tests(TestCase):\n    @classmethod\n    def setUpTestData(cls):\n        cls.owner = User.objects.create_user(\n            username="profile-owner",\n            email="profile-owner@example.com",\n            password="StrongPass2026!",\n            user_type="USER",\n        )\n\n        cls.viewer = User.objects.create_user(\n            username="profile-viewer",\n            email="profile-viewer@example.com",\n            password="StrongPass2026!",\n            user_type="USER",\n        )\n\n        cls.company = Company.objects.create(\n            name="Profile Test Company",\n            is_verified=True,\n        )\n\n        cls.published = Complaint.objects.create(\n            user=cls.owner,\n            company=cls.company,\n            status=Complaint.Status.PUBLISHED,\n            title="Public profile complaint",\n            description=(\n                "Public profile ekranında görünmesi gereken "\n                "yeterince uzun şikayet açıklaması."\n            ),\n        )\n\n        cls.resolved = Complaint.objects.create(\n            user=cls.owner,\n            company=cls.company,\n            status=Complaint.Status.RESOLVED,\n            title="Resolved profile complaint",\n            description=(\n                "Çözülmüş şikayet istatistiğini doğrulayan "\n                "yeterince uzun açıklama."\n            ),\n        )\n\n        cls.pending = Complaint.objects.create(\n            user=cls.owner,\n            company=cls.company,\n            status=Complaint.Status.PENDING,\n            title="Private pending complaint",\n            description=(\n                "Public profilde asla görünmemesi gereken "\n                "bekleyen şikayet açıklaması."\n            ),\n        )\n\n        ComplaintComment.objects.create(\n            complaint=cls.published,\n            author_user=cls.owner,\n            body="Public profile comment",\n        )\n\n        ComplaintReaction.objects.create(\n            complaint=cls.published,\n            user=cls.viewer,\n            reaction_type="👍",\n        )\n\n    def url(self):\n        return reverse(\n            "accounts:public_profile",\n            args=[self.owner.username],\n        )\n\n    def test_profile_shows_only_public_activity_and_stats(self):\n        response = self.client.get(self.url())\n\n        self.assertEqual(response.status_code, 200)\n        self.assertContains(response, self.published.title)\n        self.assertContains(response, self.resolved.title)\n        self.assertNotContains(response, self.pending.title)\n\n        self.assertEqual(response.context["complaint_count"], 2)\n        self.assertEqual(response.context["resolved_count"], 1)\n        self.assertEqual(response.context["comment_count"], 1)\n        self.assertEqual(\n            response.context["received_reaction_count"],\n            1,\n        )\n\n    def test_other_user_gets_report_button_and_hidden_modal(self):\n        self.client.force_login(self.viewer)\n        response = self.client.get(self.url())\n\n        self.assertContains(\n            response,\n            \'data-report-open="user-report-dialog"\',\n        )\n        self.assertContains(\n            response,\n            \'id="user-report-dialog"\',\n        )\n        self.assertContains(response, "hidden")\n\n    def test_self_profile_does_not_show_report_action(self):\n        self.client.force_login(self.owner)\n        response = self.client.get(self.url())\n\n        self.assertNotContains(\n            response,\n            \'data-report-open="user-report-dialog"\',\n        )\n\n    def test_existing_report_replaces_action_with_reported_state(self):\n        UserReport.objects.create(\n            reporter=self.viewer,\n            reported_user=self.owner,\n            reason=UserReport.Reason.SPAM,\n            description="Already reported.",\n        )\n\n        self.client.force_login(self.viewer)\n        response = self.client.get(self.url())\n\n        self.assertContains(response, "Raporlandı")\n        self.assertNotContains(\n            response,\n            \'data-report-open="user-report-dialog"\',\n        )\n\n    def test_complaints_are_paginated_six_per_page(self):\n        for index in range(7):\n            Complaint.objects.create(\n                user=self.owner,\n                company=self.company,\n                status=Complaint.Status.PUBLISHED,\n                title=f"Extra complaint {index}",\n                description=(\n                    "Pagination test için yeterince uzun "\n                    "şikayet açıklaması."\n                ),\n            )\n\n        response = self.client.get(self.url())\n        page = response.context["complaint_page"]\n\n        self.assertEqual(len(page), 6)\n        self.assertTrue(page.has_next())\n'
write(FILES["tests"], tests)

